    { id=20136, tab=2, tier=5, col=2, name="Выживание сильнейших", icon="ability_druid_enrage", maxRank=3, prereqTalent=0, prereqPoints=25, wired=true, tooltip={ "Увеличивает все характеристики на 1% и уменьшает вероятность получить критический удар в ближнем бою на 1%.", "Увеличивает все характеристики на 2% и уменьшает вероятность получить критический удар в ближнем бою на 2%.", "Увеличивает все характеристики на 3% и уменьшает вероятность получить критический удар в ближнем бою на 3%." } },
