    { id=20138, tab=2, tier=6, col=1, name="Вожак стаи", icon="spell_nature_unyeildingstamina", maxRank=1, prereqTalent=0, prereqPoints=30, wired=true, tooltip={ "В обличье кошки, медведя или лютого медведя способность \"Вожак стаи\" повышается вероятность нанесения критического удара всеми членами группы в радиусе 45 м. как в дальнем, так и в ближнем бою на 5%." }, grant={ [1]=946256 } },
    { id=20139, tab=2, tier=6, col=2, name="Улучшенный вожак стаи", icon="spell_nature_unyeildingstamina", maxRank=2, prereqTalent=20138, prereqPoints=30, wired=true, tooltip={ "Ваша способность \"Вожак стаи\" также дает попавшим под ее воздействие целям получить 100% шанса исцелить себя на 2% от их общего здоровья при получении критического удара в дальнем или ближнем бою. Эффект исцеления действует не чаще, чем раз в 6 сек.", "Ваша способность \"Вожак стаи\" также дает попавшим под ее воздействие целям получить 100% шанса исцелить себя на 4% от их общего здоровья при получении критического удара в дальнем или ближнем бою. Эффект исцеления действует не чаще, чем раз в 6 сек." } },
