    { id=20141, tab=2, tier=8, col=1, name="Увечье", icon="ability_druid_mangle2", maxRank=1, prereqTalent=20138, prereqPoints=40, wired=true, tooltip={ "Наносит цели урон и заставляет ее получать больше урона от кровотечения в течение 12 сек.. Можно использовать в облике кошки и лютого медведя." }, grant={ [1]=946258 } },
    { id=20142, tab=3, tier=0, col=1, name="Улучшенный знак дикой природы", icon="spell_nature_regeneration", maxRank=5, prereqTalent=0, prereqPoints=0, wired=true, tooltip={ "Усиливает эффекты \"Знака дикой природы\" и \"Дара дикой природы\" на 7%.", "Усиливает эффекты \"Знака дикой природы\" и \"Дара дикой природы\" на 14%.", "Усиливает эффекты \"Знака дикой природы\" и \"Дара дикой природы\" на 21%.", "Усиливает эффекты \"Знака дикой природы\" и \"Дара дикой природы\" на 28%.", "Усиливает эффекты \"Знака дикой природы\" и \"Дара дикой природы\" на 35%." } },
    { id=20143, tab=3, tier=0, col=2, name="Гнев", icon="spell_holy_blessingofstamina", maxRank=5, prereqTalent=0, prereqPoints=0, wired=true, tooltip={ "Дает вам 20% шанс обрести 10 ед. ярости при превращении в облик медведя или лютого медведя; или 40 ед. энергии при превращении в облик кошки.", "Дает вам 40% шанс обрести 10 ед. ярости при превращении в облик медведя или лютого медведя; или 40 ед. энергии при превращении в облик кошки.", "Дает вам 60% шанс обрести 10 ед. ярости при превращении в облик медведя или лютого медведя; или 40 ед. энергии при превращении в облик кошки.", "Дает вам 80% шанс обрести 10 ед. ярости при превращении в облик медведя или лютого медведя; или 40 ед. энергии при превращении в облик кошки.", "Дает вам 100% шанс обрести 10 ед. ярости при превращении в облик медведя или лютого медведя; или 40 ед. энергии при превращении в облик кошки." }, grant={ [1]=17056, [2]=17058, [3]=17059, [4]=17060, [5]=17061 } },
